&lt;tr&gt;
&lt;td&gt;Ropa, piel, detalle de material&lt;/td&gt;
&lt;td&gt;True Texture&lt;/td&gt;
&lt;td&gt;Optimizado para microtextura, acepta alucinación&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Retrato, realismo crítico&lt;/td&gt;
&lt;td&gt;Natural HD&lt;/td&gt;
&lt;td&gt;Falla con elegancia, sin piel cerosa&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Animación, estilizado, social&lt;/td&gt;
&lt;td&gt;Cinema Vivid&lt;/td&gt;
&lt;td&gt;Impacto de color sobre fidelidad de resolución&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Historia de daño desconocida&lt;/td&gt;
&lt;td&gt;Clear Reality&lt;/td&gt;
